def transform(grid):
    from collections import Counter
    h,w=len(grid),len(grid[0])
    cnt=Counter(x for row in grid for x in row)
    bg=cnt.most_common(1)[0][0]
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg:
                r9=[cc for cc in range(w) if grid[r][cc]!=bg]
                c9=[rr for rr in range(h) if grid[rr][c]!=bg]
                if (any(x<c for x in r9) and any(x>c for x in r9)) or (any(x<r for x in c9) and any(x>r for x in c9)):
                    out[r][c]=3
    return out
